css:
.mtm-morph-toggle{box-sizing:border-box;width:100%;padding:16px 16px 14px;border:1px solid #1c2434;border-radius:16px;background:linear-gradient(165deg,#151c2a,#0a0c12 68%);font-family:system-ui,-apple-system,"Segoe UI",Roboto,Helvetica,Arial,sans-serif;color:#e8edf7;display:flex;flex-direction:column;gap:12px}
.mtm-morph-toggle-row{display:flex;align-items:center;justify-content:space-between;gap:14px}
.mtm-morph-toggle-text{display:flex;flex-direction:column;gap:3px;min-width:0}
.mtm-morph-toggle-title{font-size:13px;font-weight:600;letter-spacing:.01em}
.mtm-morph-toggle-sub{font-size:11px;color:#7c89a3}
.mtm-morph-toggle-sw{position:relative;flex:none;width:54px;height:30px;padding:0;border:1px solid #2b3648;border-radius:999px;background:#212a3c;cursor:pointer;-webkit-appearance:none;appearance:none;transition:box-shadow .3s ease,border-color .3s ease}
.mtm-morph-toggle-sw:hover:not(:disabled){border-color:#3a4a63}
.mtm-morph-toggle-sw:focus-visible{outline:2px solid #8fb4ff;outline-offset:3px}
.mtm-morph-toggle-sw:disabled{opacity:.42;cursor:not-allowed}
.mtm-morph-toggle-fill{position:absolute;top:-1px;left:-1px;right:-1px;bottom:-1px;border-radius:999px;background:linear-gradient(100deg,#5b73ff,#9a5cf6);opacity:0;transform:scale(.55);transition:opacity .26s ease,transform .46s cubic-bezier(.34,1.5,.5,1)}
.mtm-morph-toggle-sw[aria-checked="true"] .mtm-morph-toggle-fill{opacity:1;transform:scale(1)}
.mtm-morph-toggle-ping{position:absolute;top:-1px;left:-1px;right:-1px;bottom:-1px;border-radius:999px;border:1px solid #9a5cf6;opacity:0;pointer-events:none}
.mtm-morph-toggle-sw[aria-checked="true"] .mtm-morph-toggle-ping{animation:mtm-morph-toggle-ping .62s ease-out}
.mtm-morph-toggle-knob{position:absolute;top:4px;left:4px;width:22px;height:22px;border-radius:999px;background:#eef2fd;box-shadow:0 4px 10px rgba(3,6,14,.55);display:grid;place-items:center;transition:transform .44s cubic-bezier(.34,1.5,.5,1),width .18s ease}
.mtm-morph-toggle-sw[aria-checked="true"] .mtm-morph-toggle-knob{transform:translateX(24px)}
.mtm-morph-toggle-sw:not(:disabled):active .mtm-morph-toggle-knob{width:30px}
.mtm-morph-toggle-sw[aria-checked="true"]:not(:disabled):active .mtm-morph-toggle-knob{transform:translateX(16px)}
.mtm-morph-toggle-glyph{position:absolute;width:13px;height:13px;fill:none;stroke-width:2;stroke-linecap:round;transition:opacity .22s ease,transform .42s cubic-bezier(.34,1.5,.5,1)}
.mtm-morph-toggle-g-off{stroke:#e8a13a;opacity:1;transform:rotate(0) scale(1)}
.mtm-morph-toggle-g-on{stroke:#6d4bd8;opacity:0;transform:rotate(-80deg) scale(.35)}
.mtm-morph-toggle-sw[aria-checked="true"] .mtm-morph-toggle-g-off{opacity:0;transform:rotate(80deg) scale(.35)}
.mtm-morph-toggle-sw[aria-checked="true"] .mtm-morph-toggle-g-on{opacity:1;transform:rotate(0) scale(1)}
.mtm-morph-toggle-status{margin:2px 0 0;padding-top:11px;border-top:1px solid #19202e;font-size:11px;letter-spacing:.02em;color:#8c9ab5}
@keyframes mtm-morph-toggle-ping{0%{opacity:.85;transform:scale(1)}100%{opacity:0;transform:scale(1.45)}}
@media (prefers-reduced-motion: reduce){
.mtm-morph-toggle-knob{transition:none}
.mtm-morph-toggle-fill{transition:none}
.mtm-morph-toggle-glyph{transition:none}
.mtm-morph-toggle-sw[aria-checked="true"] .mtm-morph-toggle-ping{animation:none}
}

js:
var sws = root.querySelectorAll('.mtm-morph-toggle-sw');
var status = root.querySelector('.mtm-morph-toggle-status');
function sync(){
  var on = sws[0].getAttribute('aria-checked') === 'true';
  status.textContent = on ? 'Notifications muted until 6:00 PM' : 'All alerts are coming through';
}
Array.prototype.forEach.call(sws, function(sw){
  sw.addEventListener('click', function(){
    if (sw.disabled) return;
    sw.setAttribute('aria-checked', sw.getAttribute('aria-checked') === 'true' ? 'false' : 'true');
    sync();
  });
});
sync();

css:
.mtm-tick-draw{box-sizing:border-box;width:100%;padding:15px 16px 13px;border:1px solid #172130;border-radius:14px;background:#0c1017;font-family:ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;color:#d7e3ef}
.mtm-tick-draw-head{display:flex;align-items:baseline;justify-content:space-between;gap:10px}
.mtm-tick-draw-title{font-size:11px;letter-spacing:.16em;text-transform:uppercase;color:#93a6ba}
.mtm-tick-draw-count{font-size:11px;color:#4fd6a0;transition:color .3s ease}
.mtm-tick-draw-count-full{color:#8be9c4}
.mtm-tick-draw-bar{position:relative;height:2px;margin:9px 0 11px;border-radius:2px;background:#18222f;overflow:hidden}
.mtm-tick-draw-bar-fill{display:block;height:100%;background:linear-gradient(90deg,#2dd4a0,#5eead4);transform-origin:left center;transform:scaleX(0);transition:transform .45s cubic-bezier(.4,0,.2,1)}
.mtm-tick-draw-list{list-style:none;margin:0;padding:0;display:flex;flex-direction:column;gap:2px}
.mtm-tick-draw-label{display:flex;align-items:center;gap:10px;padding:6px 6px;margin:0 -6px;border-radius:8px;cursor:pointer;transition:background .18s ease}
.mtm-tick-draw-label:hover{background:#121a26}
.mtm-tick-draw-input{position:absolute;width:1px;height:1px;opacity:0;margin:0}
.mtm-tick-draw-box{position:relative;flex:none;width:19px;height:19px;border:1.5px solid #33445c;border-radius:6px;background:#101822;display:grid;place-items:center;transition:border-color .25s ease,background .25s ease}
.mtm-tick-draw-label:hover .mtm-tick-draw-box{border-color:#48607f}
.mtm-tick-draw-input:checked + .mtm-tick-draw-box{border-color:#2dd4a0;background:rgba(45,212,160,.14)}
.mtm-tick-draw-input:focus-visible + .mtm-tick-draw-box{outline:2px solid #7dd3fc;outline-offset:3px}
.mtm-tick-draw-svg{width:13px;height:13px;fill:none;stroke:#5eead4;stroke-width:2.6;stroke-linecap:round;stroke-linejoin:round}
.mtm-tick-draw-path{stroke-dasharray:24;stroke-dashoffset:24;transition:stroke-dashoffset .34s cubic-bezier(.5,0,.3,1)}
.mtm-tick-draw-input:checked + .mtm-tick-draw-box .mtm-tick-draw-path{stroke-dashoffset:0;transition-delay:.05s}
.mtm-tick-draw-pulse{animation:mtm-tick-draw-pop .42s cubic-bezier(.34,1.6,.5,1)}
.mtm-tick-draw-text{position:relative;font-size:12.5px;letter-spacing:.01em;color:#cbd8e6;transition:color .3s ease}
.mtm-tick-draw-text::after{content:"";position:absolute;left:-1px;right:-1px;top:52%;height:1px;background:#5c6d82;transform:scaleX(0);transform-origin:left center;transition:transform .32s cubic-bezier(.5,0,.3,1)}
.mtm-tick-draw-input:checked ~ .mtm-tick-draw-text{color:#5f7085}
.mtm-tick-draw-input:checked ~ .mtm-tick-draw-text::after{transform:scaleX(1);transition-delay:.1s}
@keyframes mtm-tick-draw-pop{0%{transform:scale(1)}42%{transform:scale(1.24)}100%{transform:scale(1)}}
@media (prefers-reduced-motion: reduce){
.mtm-tick-draw-path{transition:none}
.mtm-tick-draw-text::after{transition:none}
.mtm-tick-draw-bar-fill{transition:none}
.mtm-tick-draw-pulse{animation:none}
}

js:
var inputs = root.querySelectorAll('.mtm-tick-draw-input');
var count = root.querySelector('.mtm-tick-draw-count');
var fill = root.querySelector('.mtm-tick-draw-bar-fill');
function sync(){
  var done = 0;
  Array.prototype.forEach.call(inputs, function(i){ if (i.checked) done++; });
  count.textContent = done + ' / ' + inputs.length;
  fill.style.transform = 'scaleX(' + (done / inputs.length) + ')';
  if (done === inputs.length) count.classList.add('mtm-tick-draw-count-full');
  else count.classList.remove('mtm-tick-draw-count-full');
}
Array.prototype.forEach.call(inputs, function(i){
  i.addEventListener('change', function(){
    var box = i.parentNode.querySelector('.mtm-tick-draw-box');
    box.classList.remove('mtm-tick-draw-pulse');
    void box.offsetWidth;
    if (i.checked) box.classList.add('mtm-tick-draw-pulse');
    sync();
  });
});
sync();

css:
.mtm-like-burst{box-sizing:border-box;width:100%;padding:15px 16px 13px;border:1px solid #241a20;border-radius:16px;background:radial-gradient(120% 130% at 12% 0%,#1d1418 0%,#0a0c12 62%);font-family:system-ui,-apple-system,"Segoe UI",Roboto,Helvetica,Arial,sans-serif;color:#f1e7ec}
.mtm-like-burst-meta{display:flex;align-items:baseline;justify-content:space-between;gap:10px;margin-bottom:12px}
.mtm-like-burst-name{font-size:13px;font-weight:600}
.mtm-like-burst-time{font-size:11px;color:#8b7a83}
.mtm-like-burst-bar{display:flex;align-items:center;gap:10px}
.mtm-like-burst-btn{position:relative;display:inline-flex;align-items:center;gap:9px;padding:7px 14px 7px 11px;border:1px solid #3a2833;border-radius:999px;background:#150f14;color:#cbb9c2;font:600 12px/1 inherit;cursor:pointer;-webkit-appearance:none;appearance:none;transition:border-color .2s ease,color .2s ease,background .2s ease,transform .12s ease}
.mtm-like-burst-btn:hover{border-color:#6d3549;color:#ffd7e2;background:#1b1017}
.mtm-like-burst-btn:active{transform:scale(.95)}
.mtm-like-burst-btn:focus-visible{outline:2px solid #fb7185;outline-offset:3px}
.mtm-like-burst-btn[aria-pressed="true"]{border-color:#7a2f47;color:#ffd8e2;background:#20111a}
.mtm-like-burst-glyph{position:relative;display:grid;place-items:center;width:18px;height:18px}
.mtm-like-burst-svg{width:18px;height:18px;overflow:visible}
.mtm-like-burst-out{fill:none;stroke:currentColor;stroke-width:1.7}
.mtm-like-burst-fill{fill:#f43f5e;opacity:0;transform:scale(.4);transform-origin:12px 13px;transition:opacity .18s ease,transform .3s cubic-bezier(.34,1.7,.5,1)}
.mtm-like-burst-btn[aria-pressed="true"] .mtm-like-burst-fill{opacity:1;transform:scale(1)}
.mtm-like-burst-fx{position:absolute;left:50%;top:50%;width:0;height:0;pointer-events:none}
.mtm-like-burst-ring{position:absolute;left:-13px;top:-13px;width:26px;height:26px;border:2px solid #fb7185;border-radius:999px;opacity:0}
.mtm-like-burst-p{position:absolute;left:-2.5px;top:-2.5px;width:5px;height:5px;border-radius:2px;opacity:0}
.mtm-like-burst-p:nth-child(2){--mtmlb-x:20px;--mtmlb-y:-18px;background:#fb7185}
.mtm-like-burst-p:nth-child(3){--mtmlb-x:-21px;--mtmlb-y:-14px;background:#fbbf24}
.mtm-like-burst-p:nth-child(4){--mtmlb-x:4px;--mtmlb-y:-25px;background:#f472b6}
.mtm-like-burst-p:nth-child(5){--mtmlb-x:-16px;--mtmlb-y:16px;background:#a78bfa}
.mtm-like-burst-p:nth-child(6){--mtmlb-x:19px;--mtmlb-y:13px;background:#f43f5e}
.mtm-like-burst-p:nth-child(7){--mtmlb-x:-3px;--mtmlb-y:22px;background:#fda4af}
.mtm-like-burst-go .mtm-like-burst-ring{animation:mtm-like-burst-ping .55s cubic-bezier(.2,.7,.3,1) forwards}
.mtm-like-burst-go .mtm-like-burst-p{animation:mtm-like-burst-fly .62s cubic-bezier(.2,.7,.3,1) forwards}
.mtm-like-burst-window{display:block;height:14px;overflow:hidden}
.mtm-like-burst-roll{display:block;transition:transform .36s cubic-bezier(.34,1.45,.5,1)}
.mtm-like-burst-btn[aria-pressed="true"] .mtm-like-burst-roll{transform:translateY(-14px)}
.mtm-like-burst-n{display:block;height:14px;line-height:14px;font-variant-numeric:tabular-nums}
.mtm-like-burst-chip{padding:7px 12px;border:1px solid #2a1f26;border-radius:999px;font-size:11.5px;color:#93818b}
.mtm-like-burst-out-label{margin:12px 0 0;font-size:11px;color:#8b7a83}
@keyframes mtm-like-burst-fly{0%{opacity:0;transform:translate(0,0) scale(.3)}15%{opacity:1}100%{opacity:0;transform:translate(var(--mtmlb-x),var(--mtmlb-y)) scale(.85)}}
@keyframes mtm-like-burst-ping{0%{opacity:.9;transform:scale(.25)}100%{opacity:0;transform:scale(1.7)}}
@media (prefers-reduced-motion: reduce){
.mtm-like-burst-go .mtm-like-burst-p{animation:none}
.mtm-like-burst-go .mtm-like-burst-ring{animation:none}
.mtm-like-burst-roll{transition:none}
.mtm-like-burst-fill{transition:none}
}

js:
var btn = root.querySelector('.mtm-like-burst-btn');
var glyph = root.querySelector('.mtm-like-burst-glyph');
var out = root.querySelector('.mtm-like-burst-out-label');
var timer = 0;
btn.addEventListener('click', function(){
  var on = btn.getAttribute('aria-pressed') === 'true';
  btn.setAttribute('aria-pressed', on ? 'false' : 'true');
  out.textContent = on ? '128 people liked this' : 'You and 128 others liked this';
  if (!on){
    glyph.classList.remove('mtm-like-burst-go');
    void glyph.offsetWidth;
    glyph.classList.add('mtm-like-burst-go');
    clearTimeout(timer);
    timer = setTimeout(function(){ glyph.classList.remove('mtm-like-burst-go'); }, 700);
  }
});

css:
.mtm-copy-confirm{box-sizing:border-box;width:100%;padding:14px 15px 12px;border:1px solid #182231;border-radius:14px;background:#0b0f16;font-family:system-ui,-apple-system,"Segoe UI",Roboto,Helvetica,Arial,sans-serif;color:#dbe6f4}
.mtm-copy-confirm-top{display:flex;align-items:baseline;justify-content:space-between;gap:10px;margin-bottom:9px;min-height:14px}
.mtm-copy-confirm-label{font-size:10.5px;letter-spacing:.18em;text-transform:uppercase;color:#6d7e95}
.mtm-copy-confirm-status{font-size:10.5px;letter-spacing:.04em;color:#34d399}
.mtm-copy-confirm-row{display:flex;align-items:stretch;gap:8px}
.mtm-copy-confirm-code{flex:1;min-width:0;padding:9px 11px;border:1px solid #1d2837;border-radius:9px;background:#0f1520;font-family:ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;font-size:11.5px;line-height:1.5;color:#8fd3ff;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.mtm-copy-confirm-btn{position:relative;display:inline-flex;align-items:center;gap:7px;flex:none;padding:0 13px;border:1px solid #26374b;border-radius:9px;background:#131c28;color:#cfe0f2;font:600 11.5px/1 inherit;cursor:pointer;-webkit-appearance:none;appearance:none;overflow:hidden;transition:border-color .25s ease,color .25s ease,background .25s ease}
.mtm-copy-confirm-btn:hover{border-color:#37516d;background:#17222f}
.mtm-copy-confirm-btn:active{transform:translateY(1px)}
.mtm-copy-confirm-btn:focus-visible{outline:2px solid #7dd3fc;outline-offset:3px}
.mtm-copy-confirm-btn.mtm-copy-confirm-done{border-color:#1f7a5b;color:#7ff0c4;background:#0d2119}
.mtm-copy-confirm-icons{position:relative;width:14px;height:14px;flex:none}
.mtm-copy-confirm-clip{position:absolute;inset:0;width:14px;height:14px;fill:none;stroke:currentColor;stroke-width:1.6;stroke-linecap:round;stroke-linejoin:round;transition:opacity .18s ease,transform .32s cubic-bezier(.4,0,.2,1)}
.mtm-copy-confirm-check{position:absolute;inset:0;width:14px;height:14px;fill:none;stroke:#4ade9f;stroke-width:2.6;stroke-linecap:round;stroke-linejoin:round;opacity:0;transform:scale(.6)}
.mtm-copy-confirm-tick{stroke-dasharray:24;stroke-dashoffset:24}
.mtm-copy-confirm-done .mtm-copy-confirm-clip{opacity:0;transform:scale(.5) rotate(-25deg)}
.mtm-copy-confirm-done .mtm-copy-confirm-check{opacity:1;transform:scale(1);transition:opacity .16s ease,transform .34s cubic-bezier(.34,1.6,.5,1)}
.mtm-copy-confirm-done .mtm-copy-confirm-tick{animation:mtm-copy-confirm-draw .4s cubic-bezier(.5,0,.3,1) .06s forwards}
.mtm-copy-confirm-window{display:block;height:13px;overflow:hidden}
.mtm-copy-confirm-words{display:block;transition:transform .32s cubic-bezier(.34,1.4,.5,1)}
.mtm-copy-confirm-done .mtm-copy-confirm-words{transform:translateY(-13px)}
.mtm-copy-confirm-w{display:block;height:13px;line-height:13px}
.mtm-copy-confirm-track{height:2px;margin-top:11px;border-radius:2px;background:#141d29;overflow:hidden}
.mtm-copy-confirm-fill{display:block;height:100%;background:linear-gradient(90deg,#34d399,#22d3ee);transform:scaleX(0);transform-origin:left center}
.mtm-copy-confirm-armed .mtm-copy-confirm-fill{animation:mtm-copy-confirm-drain 1.8s linear forwards}
@keyframes mtm-copy-confirm-draw{to{stroke-dashoffset:0}}
@keyframes mtm-copy-confirm-drain{0%{transform:scaleX(1)}100%{transform:scaleX(0)}}
@media (prefers-reduced-motion: reduce){
.mtm-copy-confirm-words{transition:none}
.mtm-copy-confirm-clip{transition:none}
.mtm-copy-confirm-done .mtm-copy-confirm-tick{animation:none;stroke-dashoffset:0}
.mtm-copy-confirm-armed .mtm-copy-confirm-fill{animation:none;transform:scaleX(1)}
}

js:
var btn = root.querySelector('.mtm-copy-confirm-btn');
var code = root.querySelector('.mtm-copy-confirm-code');
var status = root.querySelector('.mtm-copy-confirm-status');
var track = root.querySelector('.mtm-copy-confirm-track');
var timer = 0;
btn.addEventListener('click', function(){
  try {
    var p = navigator.clipboard && navigator.clipboard.writeText(code.textContent);
    if (p && p.then) p.then(null, function(){});
  } catch (e) {}
  btn.classList.remove('mtm-copy-confirm-done');
  track.classList.remove('mtm-copy-confirm-armed');
  void btn.offsetWidth;
  btn.classList.add('mtm-copy-confirm-done');
  track.classList.add('mtm-copy-confirm-armed');
  status.textContent = 'Copied to clipboard';
  clearTimeout(timer);
  timer = setTimeout(function(){
    btn.classList.remove('mtm-copy-confirm-done');
    track.classList.remove('mtm-copy-confirm-armed');
    status.textContent = '';
  }, 1850);
});

css:
.mtm-star-rate{box-sizing:border-box;width:100%;padding:15px 16px 13px;border:1px solid #241f14;border-radius:16px;background:linear-gradient(150deg,#191510,#0a0c12 70%);font-family:system-ui,-apple-system,"Segoe UI",Roboto,Helvetica,Arial,sans-serif;color:#f0e8d8}
.mtm-star-rate-head{display:flex;align-items:baseline;justify-content:space-between;gap:10px}
.mtm-star-rate-title{font-size:13px;font-weight:600}
.mtm-star-rate-avg{font-size:11px;color:#907f61}
.mtm-star-rate-stars{display:flex;flex-direction:row-reverse;justify-content:flex-end;gap:5px;margin:11px 0 9px}
.mtm-star-rate-lab{position:relative;display:grid;place-items:center;padding:3px;border-radius:8px;cursor:pointer}
.mtm-star-rate-lab:has(.mtm-star-rate-input:focus-visible){outline:2px solid #7dd3fc;outline-offset:1px}
.mtm-star-rate-input{position:absolute;width:1px;height:1px;opacity:0;margin:0}
.mtm-star-rate-svg{position:relative;width:26px;height:26px;overflow:visible}
.mtm-star-rate-ghost{fill:none;stroke:#4a4132;stroke-width:1.5;stroke-linejoin:round;transition:stroke .2s ease}
.mtm-star-rate-fill{fill:#f5b942;opacity:0;transform:scale(.35) rotate(-40deg);transform-origin:12px 13px;transition:opacity .18s ease,transform .42s cubic-bezier(.34,1.6,.5,1)}
.mtm-star-rate-lab:has(.mtm-star-rate-input:checked) .mtm-star-rate-fill{opacity:1;transform:scale(1) rotate(0)}
.mtm-star-rate-lab:has(.mtm-star-rate-input:checked) ~ .mtm-star-rate-lab .mtm-star-rate-fill{opacity:1;transform:scale(1) rotate(0)}
.mtm-star-rate-stars:hover .mtm-star-rate-lab:hover .mtm-star-rate-fill{opacity:1;transform:scale(1.12) rotate(0)}
.mtm-star-rate-stars:hover .mtm-star-rate-lab:hover ~ .mtm-star-rate-lab .mtm-star-rate-fill{opacity:1;transform:scale(1) rotate(0)}
.mtm-star-rate-lab:nth-child(1) .mtm-star-rate-fill{transition-delay:.16s}
.mtm-star-rate-lab:nth-child(2) .mtm-star-rate-fill{transition-delay:.12s}
.mtm-star-rate-lab:nth-child(3) .mtm-star-rate-fill{transition-delay:.08s}
.mtm-star-rate-lab:nth-child(4) .mtm-star-rate-fill{transition-delay:.04s}
.mtm-star-rate-lab:nth-child(5) .mtm-star-rate-fill{transition-delay:0s}
.mtm-star-rate-sr{position:absolute;width:1px;height:1px;overflow:hidden;clip-path:inset(50%);white-space:nowrap}
.mtm-star-rate-caption{margin:0;padding-top:10px;border-top:1px solid #221d14;font-size:11.5px;letter-spacing:.02em;color:#c8b48a;min-height:14px}
@media (prefers-reduced-motion: reduce){
.mtm-star-rate-fill{transition:none;transition-delay:0s}
.mtm-star-rate-lab:nth-child(1) .mtm-star-rate-fill{transition-delay:0s}
.mtm-star-rate-lab:nth-child(2) .mtm-star-rate-fill{transition-delay:0s}
.mtm-star-rate-lab:nth-child(3) .mtm-star-rate-fill{transition-delay:0s}
.mtm-star-rate-lab:nth-child(4) .mtm-star-rate-fill{transition-delay:0s}
}

js:
var labels = root.querySelectorAll('.mtm-star-rate-lab');
var inputs = root.querySelectorAll('.mtm-star-rate-input');
var cap = root.querySelector('.mtm-star-rate-caption');
var stars = root.querySelector('.mtm-star-rate-stars');
var words = ['Poor', 'Fair', 'Good', 'Great', 'Excellent'];
var group = 'mtm-star-rate-' + Math.random().toString(36).slice(2, 8);
Array.prototype.forEach.call(inputs, function(i){ i.name = group; });
function current(){
  var v = 0;
  Array.prototype.forEach.call(inputs, function(i){ if (i.checked) v = parseInt(i.value, 10); });
