var minus = root.querySelector('.mtm-qty-stepper-minus');
var plus = root.querySelector('.mtm-qty-stepper-plus');
var val = root.querySelector('.mtm-qty-stepper-value');
var total = root.querySelector('.mtm-qty-stepper-total');
var qty = 3, MIN = 1, MAX = 10, PRICE = 18;
var repeat = 0, delay = 0, repeated = false;
function render(dir){
  val.classList.remove('mtm-qty-stepper-up', 'mtm-qty-stepper-down');
  total.classList.remove('mtm-qty-stepper-flash');
  void val.offsetWidth;
  val.textContent = qty;
  total.textContent = '$' + (qty * PRICE).toFixed(2);
  if (dir > 0) val.classList.add('mtm-qty-stepper-up');
  if (dir < 0) val.classList.add('mtm-qty-stepper-down');
  if (dir) total.classList.add('mtm-qty-stepper-flash');
  minus.disabled = qty <= MIN;
  plus.disabled = qty >= MAX;
}
function step(dir){
  var next = Math.min(MAX, Math.max(MIN, qty + dir));
  if (next === qty) return false;
  qty = next;
  render(dir);
  return true;
}
function stop(){ clearTimeout(delay); clearInterval(repeat); }
function hold(dir){
  stop();
  delay = setTimeout(function(){
    repeat = setInterval(function(){
      if (!root.isConnected) { stop(); return; }
      repeated = true;
      if (!step(dir)) stop();
    }, 115);
  }, 420);
}
[[minus, -1], [plus, 1]].forEach(function(pair){
  var b = pair[0], d = pair[1];
  b.addEventListener('click', function(){
    if (repeated) { repeated = false; return; }
    step(d);
  });
  b.addEventListener('pointerdown', function(){ repeated = false; hold(d); });
  b.addEventListener('pointerup', stop);
  b.addEventListener('pointerleave', stop);
  b.addEventListener('pointercancel', stop);
  b.addEventListener('blur', stop);
});
render(0);

