var tabs = root.querySelectorAll('.mtm-tab-slide-tab');
var panels = root.querySelectorAll('.mtm-tab-slide-panel');
var ind = root.querySelector('.mtm-tab-slide-ind');
var timer = 0;
function place(animate){
  var idx = 0;
  Array.prototype.forEach.call(tabs, function(b, n){
    if (b.getAttribute('aria-selected') === 'true') idx = n;
  });
  var el = tabs[idx];
  ind.style.width = el.offsetWidth + 'px';
  ind.style.transform = 'translateX(' + el.offsetLeft + 'px)';
  if (animate){
    ind.classList.remove('mtm-tab-slide-stretch');
    void ind.offsetWidth;
    ind.classList.add('mtm-tab-slide-stretch');
    clearTimeout(timer);
    timer = setTimeout(function(){ ind.classList.remove('mtm-tab-slide-stretch'); }, 210);
  }
}
function select(idx, moveFocus){
  Array.prototype.forEach.call(tabs, function(b, n){
    var on = n === idx;
    b.setAttribute('aria-selected', on ? 'true' : 'false');
    b.tabIndex = on ? 0 : -1;
    if (on) panels[n].classList.add('mtm-tab-slide-panel-on');
    else panels[n].classList.remove('mtm-tab-slide-panel-on');
    panels[n].setAttribute('aria-hidden', on ? 'false' : 'true');
  });
  if (moveFocus) tabs[idx].focus();
  place(true);
}
Array.prototype.forEach.call(tabs, function(b, n){
  b.addEventListener('click', function(){ select(n, false); });
  b.addEventListener('keydown', function(e){
    var k = e.key, i = -1;
    if (k === 'ArrowRight') i = (n + 1) % tabs.length;
    else if (k === 'ArrowLeft') i = (n - 1 + tabs.length) % tabs.length;
    else if (k === 'Home') i = 0;
    else if (k === 'End') i = tabs.length - 1;
    if (i > -1){ e.preventDefault(); select(i, true); }
  });
});
requestAnimationFrame(function(){
  if (!root.isConnected) return;
  place(false);
});

