var pill = root.querySelector('.mtm-seg-slide-pill');
var segs = Array.prototype.slice.call(root.querySelectorAll('.mtm-seg-slide-seg'));
var nEl = root.querySelector('.mtm-seg-slide-n');
var copyEl = root.querySelector('.mtm-seg-slide-copy');
var settle = 0;
var current = segs[0];

function place(el, animate) {
  var l = el.offsetLeft, w = el.offsetWidth;
  if (!w) return;
  clearTimeout(settle);
  if (!animate) {
    pill.style.transition = 'none';
    pill.style.left = l + 'px';
    pill.style.width = w + 'px';
    void pill.offsetWidth;
    pill.style.transition = '';
    return;
  }
  var cl = pill.offsetLeft, cw = pill.offsetWidth;
  var a = Math.min(cl, l), b = Math.max(cl + cw, l + w);
  pill.style.left = a + 'px';
  pill.style.width = (b - a) + 'px';
  settle = setTimeout(function () {
    pill.style.left = l + 'px';
    pill.style.width = w + 'px';
  }, 130);
}

function select(el, animate) {
  current = el;
  segs.forEach(function (s) {
    var on = s === el;
    s.setAttribute('aria-selected', on ? 'true' : 'false');
    s.tabIndex = on ? 0 : -1;
    if (on) { s.classList.add('mtm-seg-slide-on'); } else { s.classList.remove('mtm-seg-slide-on'); }
  });
  place(el, animate);
  nEl.textContent = el.getAttribute('data-n');
  copyEl.textContent = el.getAttribute('data-copy');
  if (animate) {
    nEl.classList.remove('mtm-seg-slide-bump');
    void nEl.offsetWidth;
    nEl.classList.add('mtm-seg-slide-bump');
  }
}

segs.forEach(function (s, i) {
  s.addEventListener('click', function () { select(s, true); });
  s.addEventListener('keydown', function (e) {
    var d = e.key === 'ArrowRight' ? 1 : e.key === 'ArrowLeft' ? -1 : 0;
    if (!d) return;
    e.preventDefault();
    var t = segs[(i + d + segs.length) % segs.length];
    t.focus();
    select(t, true);
  });
});

select(segs[0], false);
requestAnimationFrame(function () {
  if (!root.isConnected) return;
  place(current, false);
});

