var input = root.querySelector('.mtm-agree-check-input');
var go = root.querySelector('.mtm-agree-check-go');
var hint = root.querySelector('.mtm-agree-check-hint');
var busy = false;
var t = 0;

function sync() {
  go.disabled = !input.checked || busy;
  hint.textContent = busy ? 'Provisioning — this takes a few seconds'
    : input.checked ? 'Ready when you are' : 'Required to continue';
}

input.addEventListener('change', sync);

go.addEventListener('click', function () {
  if (go.disabled) return;
  busy = true;
  go.textContent = 'Creating…';
  root.classList.add('mtm-agree-check-sent');
  sync();
  clearTimeout(t);
  t = setTimeout(function () {
    busy = false;
    go.textContent = 'Create workspace';
    root.classList.remove('mtm-agree-check-sent');
    sync();
  }, 1900);
});

