var up = root.querySelector('.mtm-vote-flick-up');
var down = root.querySelector('.mtm-vote-flick-down');
var score = root.querySelector('.mtm-vote-flick-score');
var sparks = root.querySelectorAll('.mtm-vote-flick-spark i');
var angles = ['-52deg', '-26deg', '0deg', '26deg', '52deg'];
var base = 218;
var vote = 0;

Array.prototype.forEach.call(sparks, function (s, i) {
  s.style.setProperty('--mtm-vote-flick-a', angles[i]);
});

function render(dir) {
  var n = base + vote;
  score.textContent = n;
  up.setAttribute('aria-pressed', vote === 1 ? 'true' : 'false');
  down.setAttribute('aria-pressed', vote === -1 ? 'true' : 'false');
  score.classList.remove('mtm-vote-flick-roll-up', 'mtm-vote-flick-roll-down');
  void score.offsetWidth;
  score.classList.add(dir > 0 ? 'mtm-vote-flick-roll-up' : 'mtm-vote-flick-roll-down');
}

function burst() {
  root.classList.remove('mtm-vote-flick-pop');
  void root.offsetWidth;
  root.classList.add('mtm-vote-flick-pop');
}

up.addEventListener('click', function () {
  var was = vote;
  vote = vote === 1 ? 0 : 1;
  render(vote - was);
  if (vote === 1) burst();
});

down.addEventListener('click', function () {
  var was = vote;
  vote = vote === -1 ? 0 : -1;
  render(vote - was);
});

