var val = root.querySelector('.mtm-key-copy-value');
var eye = root.querySelector('.mtm-key-copy-eye');
var btn = root.querySelector('.mtm-key-copy-btn');
var status = root.querySelector('.mtm-key-copy-status');
var idle = 'Rotates automatically on 14 Sep';
var shown = false;
var t = 0;

eye.addEventListener('click', function () {
  shown = !shown;
  eye.setAttribute('aria-pressed', shown ? 'true' : 'false');
  eye.setAttribute('aria-label', shown ? 'Hide key' : 'Reveal key');
  val.textContent = val.getAttribute(shown ? 'data-full' : 'data-mask');
});

btn.addEventListener('click', function () {
  var text = val.getAttribute('data-full');
  var ok = false;
  try {
    if (navigator.clipboard && navigator.clipboard.writeText) {
      var p = navigator.clipboard.writeText(text);
      if (p && p.then) p.then(null, function () {});
      ok = true;
    }
  } catch (e) { ok = false; }
  if (!ok) {
    try {
      var sel = window.getSelection();
      var r = document.createRange();
      r.selectNodeContents(val);
      sel.removeAllRanges();
      sel.addRange(r);
      document.execCommand('copy');
      sel.removeAllRanges();
    } catch (e2) {}
  }
  root.classList.remove('mtm-key-copy-ok');
  void root.offsetWidth;
  root.classList.add('mtm-key-copy-ok');
  status.textContent = 'Copied — paste it into your .env';
  clearTimeout(t);
  t = setTimeout(function () {
    root.classList.remove('mtm-key-copy-ok');
    status.textContent = idle;
  }, 1900);
});

