js:
var cells = Array.prototype.slice.call(root.querySelectorAll('.mtm-heat-rate-cell'));
var inputs = Array.prototype.slice.call(root.querySelectorAll('.mtm-heat-rate-input'));
var wrap = root.querySelector('.mtm-heat-rate-cells');
var word = root.querySelector('.mtm-heat-rate-word');
var words = ['Rough call', 'Needs work', 'It was fine', 'Good call', 'Excellent'];
var name = 'mtm-heat-rate-' + Math.random().toString(36).slice(2, 8);
var value = 0;

inputs.forEach(function (i) { i.name = name; });

function paint(level, hint) {
  cells.forEach(function (c, i) {
    var on = !hint && i < level;
    var soft = hint && i < level;
    if (on) { c.classList.add('mtm-heat-rate-on'); } else { c.classList.remove('mtm-heat-rate-on'); }
    if (soft) { c.classList.add('mtm-heat-rate-hint'); } else { c.classList.remove('mtm-heat-rate-hint'); }
  });
  for (var n = 1; n <= 5; n++) root.classList.remove('mtm-heat-rate-l' + n);
  if (level) root.classList.add('mtm-heat-rate-l' + level);
}

function commit(level) {
  value = level;
  paint(value, false);
  word.textContent = words[level - 1];
  word.classList.remove('mtm-heat-rate-swap');
  void word.offsetWidth;
  word.classList.add('mtm-heat-rate-swap');
  cells.forEach(function (c, i) {
    if (i === level - 1) { c.classList.add('mtm-heat-rate-pick'); } else { c.classList.remove('mtm-heat-rate-pick'); }
  });
}

cells.forEach(function (c, i) {
  c.addEventListener('mouseenter', function () { if (!value) paint(i + 1, true); });
  inputs[i].addEventListener('change', function () { commit(i + 1); });
});

wrap.addEventListener('mouseleave', function () { paint(value, false); });

