js:
var pad = root.querySelector('.mtm-hold-stepper-pad');
var digits = root.querySelector('.mtm-hold-stepper-digits');
var total = root.querySelector('.mtm-hold-stepper-total');
var minus = root.querySelector('.mtm-hold-stepper-minus');
var plus = root.querySelector('.mtm-hold-stepper-plus');
var val = 12, min = 1, max = 99, timer = 0;

function stop() { clearTimeout(timer); timer = 0; }

function render(dir) {
  digits.textContent = val;
  digits.classList.remove('mtm-hold-stepper-up', 'mtm-hold-stepper-down');
  if (dir) {
    void digits.offsetWidth;
    digits.classList.add(dir > 0 ? 'mtm-hold-stepper-up' : 'mtm-hold-stepper-down');
  }
  total.textContent = '£' + (val * 0.42).toFixed(2);
  minus.disabled = val <= min;
  plus.disabled = val >= max;
}

function step(d) {
  var next = Math.min(max, Math.max(min, val + d));
  if (next === val) {
    stop();
    pad.classList.remove('mtm-hold-stepper-shake');
    void pad.offsetWidth;
    pad.classList.add('mtm-hold-stepper-shake');
    return false;
  }
  val = next;
  render(d);
  return true;
}

function repeat(d, wait) {
  timer = setTimeout(function () {
    if (!root.isConnected) { stop(); return; }
    if (step(d)) repeat(d, Math.max(46, wait - 14));
  }, wait);
}

function wire(btn, d) {
  btn.addEventListener('pointerdown', function (e) {
    if (btn.disabled) return;
    btn.setAttribute('data-held', '1');
    try { btn.setPointerCapture(e.pointerId); } catch (err) {}
    if (step(d)) repeat(d, 400);
  });
  ['pointerup', 'pointercancel', 'blur'].forEach(function (ev) {
    btn.addEventListener(ev, stop);
  });
  btn.addEventListener('click', function () {
    if (btn.getAttribute('data-held') === '1') { btn.setAttribute('data-held', '0'); return; }
    step(d);
  });
}

wire(minus, -1);
wire(plus, 1);
render(0);

