js:
var btn = root.querySelector('.mtm-dl-morph-btn');
var arc = root.querySelector('.mtm-dl-morph-arc');
var pct = root.querySelector('.mtm-dl-morph-pct');
var status = root.querySelector('.mtm-dl-morph-status');
var LEN = 2 * Math.PI * 18.5;
var raf = 0, reset = 0, t0 = 0, state = 'idle';

arc.style.strokeDasharray = LEN;

function state_(s) {
  state = s;
  root.classList.remove('mtm-dl-morph-busy', 'mtm-dl-morph-done');
  if (s !== 'idle') root.classList.add('mtm-dl-morph-' + s);
}

function progress(p) {
  arc.style.strokeDashoffset = LEN * (1 - p);
  pct.textContent = Math.round(p * 100) + '%';
}

function tick(now) {
  if (!root.isConnected) return;
  if (!t0) t0 = now;
  var p = Math.min(1, (now - t0) / 1900);
  progress(p);
  if (p < 1) {
    raf = requestAnimationFrame(tick);
    return;
  }
  state_('done');
  status.textContent = 'Saved to Downloads';
  btn.setAttribute('aria-label', 'Download q3-forecast.xlsx again');
  reset = setTimeout(function () {
    state_('idle');
    progress(0);
    status.textContent = 'Ready to download';
  }, 2400);
}

btn.addEventListener('click', function () {
  if (state === 'busy') {
    cancelAnimationFrame(raf);
    state_('idle');
    progress(0);
    status.textContent = 'Download cancelled';
    return;
  }
  clearTimeout(reset);
  cancelAnimationFrame(raf);
  t0 = 0;
  progress(0);
  state_('busy');
  status.textContent = 'Downloading 2.4 MB…';
  raf = requestAnimationFrame(tick);
});

progress(0);

