js:
var btn = root.querySelector('.mtm-play-morph-btn');
var prog = root.querySelector('.mtm-play-morph-prog');
var now = root.querySelector('.mtm-play-morph-now');
var end = root.querySelector('.mtm-play-morph-end');
var DUR = 200;
var t = 0, timer = 0, playing = false;

function fmt(s) {
  s = Math.max(0, Math.round(s));
  return Math.floor(s / 60) + ':' + ('0' + (s % 60)).slice(-2);
}

function paint() {
  prog.style.width = (t / DUR * 100) + '%';
  now.textContent = fmt(t);
  end.textContent = '-' + fmt(DUR - t);
}

function stop() { clearInterval(timer); timer = 0; }

function setPlaying(on) {
  playing = on;
  btn.setAttribute('aria-pressed', on ? 'true' : 'false');
  btn.setAttribute('aria-label', (on ? 'Pause' : 'Play') + ' Night Shift Radio');
  if (on) { root.classList.add('mtm-play-morph-on'); } else { root.classList.remove('mtm-play-morph-on'); }
  stop();
  if (!on) return;
  timer = setInterval(function () {
    if (!root.isConnected) { stop(); return; }
    t += 0.25;
    if (t >= DUR) { t = 0; setPlaying(false); }
    paint();
  }, 250);
}

btn.addEventListener('click', function () { setPlaying(!playing); });

paint();
